{
  "technical_and_design_decisions": [
    "Leverage existing Spring XD Ambari service definitions and modify blueprint templates to support Spring XD on YARN deployments.",
    "Adopt Spring Cloud Config Client within spring-bus to dynamically fetch externalized configuration properties at bootstrap.",
    "Use JMH (Java Microbenchmark Harness) and Spring Integration performance profiling tools to measure SI 4.2 channel throughput and latency.",
    "Ensure Hadoop configuration parsing in jdbchdfs handles 'file://' URI schemas gracefully by binding to org.apache.hadoop.fs.LocalFileSystem.",
    "Expose dynamic system property options in Sqoop job runner parameters to pass custom JVM arguments to child processes."
  ],
  "assumptions": [
    "A working Hadoop/YARN cluster environment and Ambari test environment are available for integration testing.",
    "Spring Cloud Config Server is already operational or can be mocked during local module development.",
    "Target runtime baseline remains consistent with Java 17+ requirements for Spring 6 framework ecosystem where applicable.",
    "Documentation will be published in standard markdown / Spring project documentation format."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Implement Ambari Support for Spring XD on YARN (U1)",
      "activity_description": "Enhance the Apache Ambari service definition and scripts to install, configure, and manage Spring XD clusters running on YARN.",
      "most_likely_effort": 3.5
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Integrate Spring Cloud Config into spring-bus (U2)",
      "activity_description": "Configure spring-bus modules to retrieve configuration properties centrally via spring-cloud-config server during bootstrap.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Investigate Spring Integration 4.2 Channel Performance (U3)",
      "activity_description": "Set up performance profiling benchmarks for SI 4.2 message channels, identify throughput bottlenecks, and produce optimization recommendations.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Measure Spring XD Baseline Serialization Characteristics (U4)",
      "activity_description": "Develop baseline serialization test suites for Spring XD tuple/payload types and document memory footprint and performance metrics.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Review spring-bus Architecture & Refactor Gaps (U5)",
      "activity_description": "Conduct architectural review of spring-bus design specifications and refactor core foundational contracts to resolve identified design gaps.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Ambari Plugin Upgrade to Spring XD 1.2 GA & User Docs (U6)",
      "activity_description": "Update Ambari plugin definitions from Spring XD 1.2 RC to 1.2 GA release bits and update upgrade documentation.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Support LocalFileSystem via fsUri=file:// in jdbchdfs (U7)",
      "activity_description": "Modify jdbchdfs job configuration parser to correctly instantiate Hadoop LocalFileSystem when fsUri is set to file://.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Enable System Properties Passing to Sqoop Job Process (U8)",
      "activity_description": "Add configuration parameter support to pass arbitrary JVM system properties down to the standalone Sqoop Java execution process.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "Integration Testing and Verification",
      "activity_description": "Perform overall verification, unit/integration testing, and validation across modified Spring XD, Bus, and Integration modules.",
      "most_likely_effort": 2.5
    }
  ],
  "reported_total": {
    "most_likely_effort": 21.5
  }
}
